def transform(grid):
    h, w = len(grid), len(grid[0])
    g = [row[:] for row in grid]

    # Find the full row or column that acts as the divider.
    divider = None
    for r in range(h):
        if len(set(grid[r])) == 1 and grid[r][0] == 2:
            divider = ('h', r)
            break
    if divider is None:
        for c in range(w):
            if all(grid[r][c] == 2 for r in range(h)):
                divider = ('v', c)
                break

    # The most common non-divider color is the background.
    counts = {}
    for row in grid:
        for x in row:
            if x != 2:
                counts[x] = counts.get(x, 0) + 1
    background = max(counts, key=counts.get)

    points = [(r, c) for r in range(h) for c in range(w)
              if grid[r][c] not in (2, background)]
    if not points or divider is None:
        return g

    axis, d = divider
    if axis == 'h':
        rmin = min(r for r, c in points)
        rmax = max(r for r, c in points)
        if rmin > d:
            shift = d + 1 - rmin
            new_points = [(r + shift, c) for r, c in points]
            edge = max(r for r, c in new_points)
            marker = edge + 1
        else:
            shift = d - 1 - rmax
            new_points = [(r + shift, c) for r, c in points]
            edge = min(r for r, c in new_points)
            marker = edge - 1
        for r, c in points:
            g[r][c] = background
        for (r, c), (nr, nc) in zip(points, new_points):
            g[nr][nc] = grid[r][c]
        if 0 <= marker < h:
            g[marker] = [8] * w
    else:
        cmin = min(c for r, c in points)
        cmax = max(c for r, c in points)
        if cmin > d:
            shift = d + 1 - cmin
            new_points = [(r, c + shift) for r, c in points]
            edge = max(c for r, c in new_points)
            marker = edge + 1
        else:
            shift = d - 1 - cmax
            new_points = [(r, c + shift) for r, c in points]
            edge = min(c for r, c in new_points)
            marker = edge - 1
        for r, c in points:
            g[r][c] = background
        for (r, c), (nr, nc) in zip(points, new_points):
            g[nr][nc] = grid[r][c]
        if 0 <= marker < w:
            for r in range(h):
                g[r][marker] = 8

    return g
